// Art deco luxury pricing card: stepped gilt frame, fan corner ornaments, sunburst behind the price and a gold foil CTA.
export const meta = {
  title: "Gilded Deco Tier",
  kind: "ui",
  description: "An art deco pricing card in black and gold with a stepped geometric frame, fan corners, a sunburst price and a foil button, for luxury memberships, premium SaaS tiers and high-end landing pages.",
  tags: ["art deco", "pricing card", "luxury", "gold", "membership", "premium", "gatsby", "ui"],
  price: 7,
  author: "Pat Liu",
  size: [480, 640],
};

export const params = {
  knobs: {
    gold: { type: "color", label: "Gold leaf", default: "#D4AF37" },
    ground: { type: "color", label: "Card ground", default: "#0C0C0E" },
    backdrop: { type: "color", label: "Backdrop", default: "#050505" },
    frame: { type: "choice", label: "Frame style", default: "stepped", options: ["stepped", "double line", "chevron"] },
    period: { type: "choice", label: "Billing period", default: "month", options: ["month", "year", "user / month"] },
    plan: { type: "text", label: "Plan name", default: "Sovereign" },
    price: { type: "text", label: "Price", default: "$49" },
    features: { type: "range", label: "Feature rows", default: 5, min: 3, max: 6, step: 1 },
    rays: { type: "range", label: "Sunburst rays", default: 28, min: 12, max: 48, step: 4 },
    popular: { type: "toggle", label: "Members' choice badge", default: true },
  },
  presets: {
    Gatsby: { gold: "#D4AF37", ground: "#0C0C0E", backdrop: "#050505" },
    "Emerald Deco": { gold: "#D9B65C", ground: "#0B2A22", backdrop: "#06140F" },
    "Ivory Deco": { gold: "#A8832E", ground: "#F6F0E1", backdrop: "#E2D8C0" },
  },
};

const FEATURES = [
  "Unlimited private suites",
  "Dedicated concierge",
  "Priority reservations",
  "Bespoke itineraries",
  "Lounge access worldwide",
  "Gold card &amp; insignia",
];
const NOTES = {
  month: "Billed monthly · cancel anytime",
  year: "Billed annually · two months complimentary",
  "user / month": "Per member · billed monthly",
};
const F = "Didot, 'Bodoni 72', 'Bodoni MT', Georgia, 'Times New Roman', serif";

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const f1 = (v) => (+v).toFixed(1);
function rgb(h) {
  const n = parseInt(String(h).slice(1, 7), 16) || 0;
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function mix(a, b, t) {
  const x = rgb(a), y = rgb(b);
  return "#" + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, "0")).join("");
}
const lum = (h) => { const [r, g, b] = rgb(h); return (0.299 * r + 0.587 * g + 0.114 * b) / 255; };
const ink = (h) => (lum(h) > 0.55 ? "#17120A" : "#FFF8E6");

function stepPath(x, y, w, h, s) {
  const R = x + w, B = y + h, s2 = s * 2;
  return `M${f1(x + s2)} ${y}H${f1(R - s2)}V${f1(y + s)}H${f1(R - s)}V${f1(y + s2)}H${R}V${f1(B - s2)}H${f1(R - s)}V${f1(B - s)}H${f1(R - s2)}V${B}H${f1(x + s2)}V${f1(B - s)}H${f1(x + s)}V${f1(B - s2)}H${x}V${f1(y + s2)}H${f1(x + s)}V${f1(y + s)}H${f1(x + s2)}Z`;
}
function octPath(x, y, w, h, c) {
  const R = x + w, B = y + h;
  return `M${f1(x + c)} ${y}H${f1(R - c)}L${R} ${f1(y + c)}V${f1(B - c)}L${f1(R - c)} ${B}H${f1(x + c)}L${x} ${f1(B - c)}V${f1(y + c)}Z`;
}

export default function render(p) {
  const W = 480, H = 640;
  const gold = p.gold, ground = p.ground;
  const light = lum(ground) > 0.5;
  const text = light ? "#1C1710" : "#F3EAD3";
  const muted = mix(text, ground, 0.42);
  const gInk = light ? mix(gold, "#000000", 0.2) : gold;
  const pop = !!p.popular;
  const style = p.frame;

  const n = clamp(Math.round(p.features), 3, 6);
  const rays = clamp(Math.round(p.rays), 6, 64);
  const cw = 360, cx = (W - cw) / 2;
  const rowY0 = 292, gap = 32;
  const btnY = rowY0 + (n - 1) * gap + 40;
  const ch = btnY + 100;
  const cy = Math.round((H - ch) / 2) + (pop ? 4 : 0);
  const mid = cw / 2;

  const shape = (i) => {
    const x = i, y = i, w = cw - 2 * i, h = ch - 2 * i;
    if (style === "stepped") return stepPath(x, y, w, h, Math.max(4, 10 - i * 0.3));
    if (style === "chevron") return octPath(x, y, w, h, Math.max(8, 26 - i * 0.6));
    return `M${x} ${y}H${x + w}V${y + h}H${x}Z`;
  };

  const hi = mix(gold, "#FFFFFF", 0.5), lo = mix(gold, "#000000", 0.38);
  const defs = `<defs>
<linearGradient id="foil" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hi}"/><stop offset="0.38" stop-color="${gold}"/><stop offset="0.56" stop-color="${lo}"/><stop offset="0.82" stop-color="${mix(gold, "#FFFFFF", 0.25)}"/><stop offset="1" stop-color="${mix(gold, "#000000", 0.18)}"/></linearGradient>
<linearGradient id="foilD" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${mix(gInk, "#FFFFFF", light ? 0.1 : 0.4)}"/><stop offset="0.5" stop-color="${gInk}"/><stop offset="1" stop-color="${mix(gInk, "#000000", 0.25)}"/></linearGradient>
<radialGradient id="burst" gradientUnits="userSpaceOnUse" cx="${mid}" cy="172" r="118"><stop offset="0.12" stop-color="${gold}" stop-opacity="${light ? 0.34 : 0.3}"/><stop offset="1" stop-color="${gold}" stop-opacity="0"/></radialGradient>
<radialGradient id="bd" gradientUnits="userSpaceOnUse" cx="${W / 2}" cy="${H}" r="${H}"><stop offset="0" stop-color="${gold}" stop-opacity="${light ? 0.16 : 0.1}"/><stop offset="1" stop-color="${gold}" stop-opacity="0"/></radialGradient>
<filter id="sh" x="-30%" y="-20%" width="160%" height="150%"><feDropShadow dx="0" dy="20" stdDeviation="22" flood-color="${pop && !light ? gold : "#000000"}" flood-opacity="${light ? 0.18 : pop ? 0.2 : 0.55}"/></filter>
</defs>`;

  let bgRays = "";
  const bn = 24;
  for (let i = 0; i < bn; i++) {
    const a0 = Math.PI + (i / bn) * Math.PI, a1 = a0 + Math.PI / bn / 2;
    bgRays += `M${W / 2} ${H}L${f1(W / 2 + Math.cos(a0) * 900)} ${f1(H + Math.sin(a0) * 900)}L${f1(W / 2 + Math.cos(a1) * 900)} ${f1(H + Math.sin(a1) * 900)}Z`;
  }
  const bgLayer = `<rect width="${W}" height="${H}" fill="${p.backdrop}"/><path d="${bgRays}" fill="url(#bd)"/>`;

  let burst = "";
  for (let i = 0; i < rays; i++) {
    const a0 = (i / rays) * Math.PI * 2 - Math.PI / 2, a1 = a0 + Math.PI / rays;
    burst += `M${mid} 172L${f1(mid + Math.cos(a0) * 130)} ${f1(172 + Math.sin(a0) * 130)}L${f1(mid + Math.cos(a1) * 130)} ${f1(172 + Math.sin(a1) * 130)}Z`;
  }

  const fc = style === "chevron" ? 28 : 26;
  const fan = (x, y, sx, sy) => {
    const r = [22.5, 45, 67.5].map((a) => { const t = (a * Math.PI) / 180; return `M0 0L${f1(Math.cos(t) * 20)} ${f1(Math.sin(t) * 20)}`; }).join("");
    return `<g transform="translate(${x} ${y}) scale(${sx} ${sy})" fill="none" stroke="${gInk}" stroke-width="1"><path d="M10 0A10 10 0 0 1 0 10M20 0A20 20 0 0 1 0 20${r}"/><path d="M5 0A5 5 0 0 1 0 5L0 0Z" fill="${gInk}" stroke="none"/></g>`;
  };
  const fans = fan(fc, fc, 1, 1) + fan(cw - fc, fc, -1, 1) + fan(fc, ch - fc, 1, -1) + fan(cw - fc, ch - fc, -1, -1);

  const diamond = (x, y, s) => `<path d="M${x} ${y - s}L${x + s} ${y}L${x} ${y + s}L${x - s} ${y}Z" fill="${gInk}"/>`;
  const rule = (y, half, triple) =>
    `<path d="M${mid - half} ${y}H${mid - (triple ? 22 : 12)}M${mid + (triple ? 22 : 12)} ${y}H${mid + half}" stroke="${gInk}" stroke-width="1"/>` +
    diamond(mid, y, 4.5) + (triple ? diamond(mid - 13, y, 2.5) + diamond(mid + 13, y, 2.5) : "");

  let rows = "";
  for (let i = 0; i < n; i++) {
    const y = rowY0 + i * gap;
    rows += `<path d="M64 ${y - 9}L70 ${y - 3}L64 ${y + 3}L58 ${y - 3}Z" fill="none" stroke="${gInk}" stroke-width="1.2"/>${diamond(64, y - 3, 2)}`;
    rows += `<text x="84" y="${y + 2}" font-size="15" fill="${text}" fill-opacity="0.92">${FEATURES[i]}</text>`;
  }

  const bx = 52, bw = cw - 104, bh = 48, c = 14;
  const btn = `<path d="M${bx + c} ${btnY}H${bx + bw - c}L${bx + bw} ${btnY + bh / 2}L${bx + bw - c} ${btnY + bh}H${bx + c}L${bx} ${btnY + bh / 2}Z" fill="url(#foil)"/>
<path d="M${bx + c + 2} ${btnY + 4}H${bx + bw - c - 2}L${bx + bw - 5} ${btnY + bh / 2}L${bx + bw - c - 2} ${btnY + bh - 4}H${bx + c + 2}L${bx + 5} ${btnY + bh / 2}Z" fill="none" stroke="${mix(gold, "#000000", 0.45)}" stroke-opacity="0.5" stroke-width="0.8"/>
<text x="${mid}" y="${btnY + 29}" text-anchor="middle" font-size="13" font-weight="700" letter-spacing="3" fill="${ink(gold)}">RESERVE YOUR PLACE</text>`;

  const planRaw = String(p.plan || "").slice(0, 18).toUpperCase();
  const priceRaw = String(p.price || "").slice(0, 9);
  const planFs = clamp(250 / (Math.max(1, planRaw.length) * 0.92), 14, 26);
  const priceFs = clamp(210 / (Math.max(1, priceRaw.length) * 0.6), 34, 58);
  const perLabel = "PER " + esc(p.period.toUpperCase());

  const bdgW = 168;
  const badge = pop
    ? `<g transform="translate(${mid} 0)"><path d="M${-bdgW / 2} 0L${-bdgW / 2 + 12} -13H${bdgW / 2 - 12}L${bdgW / 2} 0L${bdgW / 2 - 12} 13H${-bdgW / 2 + 12}Z" fill="url(#foil)" stroke="${ground}" stroke-width="3" paint-order="stroke"/><text x="0" y="3.8" text-anchor="middle" font-size="10" font-weight="700" letter-spacing="2.6" fill="${ink(gold)}">MEMBERS&#8217; CHOICE</text></g>`
    : "";

  const card = `<g transform="translate(${cx} ${cy})">
<path d="${shape(0)}" fill="${ground}" filter="url(#sh)"/>
<path d="${burst}" fill="url(#burst)"/>
<path d="${shape(0)}" fill="none" stroke="${gInk}" stroke-width="${pop ? 1.6 : 1}" stroke-opacity="${pop ? 1 : 0.55}"/>
<path d="${shape(12)}" fill="none" stroke="${gInk}" stroke-width="1.2"/>
<path d="${shape(style === "double line" ? 16 : 17)}" fill="none" stroke="${gInk}" stroke-width="0.6" stroke-opacity="0.6"/>
${fans}
${rule(46, 64, false)}
<text x="${mid}" y="${84}" text-anchor="middle" font-size="${f1(planFs)}" font-weight="700" letter-spacing="5" fill="url(#foilD)">${esc(planRaw)}</text>
<text x="${mid}" y="106" text-anchor="middle" font-size="13" font-style="italic" fill="${muted}">For those who expect the finest</text>
<text x="${mid}" y="${f1(170 + priceFs * 0.34)}" text-anchor="middle" font-size="${f1(priceFs)}" font-weight="400" letter-spacing="-1" fill="${text}">${esc(priceRaw)}</text>
<text x="${mid}" y="${f1(196 + priceFs * 0.34)}" text-anchor="middle" font-size="11" letter-spacing="3.2" fill="${gInk}">${perLabel}</text>
<text x="${mid}" y="${f1(218 + priceFs * 0.34)}" text-anchor="middle" font-size="12" font-style="italic" fill="${muted}">${esc(NOTES[p.period] || "")}</text>
${rule(260, 108, true)}
${rows}
${btn}
<text x="${mid}" y="${btnY + 76}" text-anchor="middle" font-size="11" letter-spacing="1.6" fill="${muted}">NO CREDIT CARD REQUIRED</text>
${badge}
</g>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">${defs}${bgLayer}<g font-family="${F}">${card}</g></svg>`;
}
